SELECT	b.apr01_status_cd
  FROM	emp45_eval_relate_appr
  		LEFT OUTER JOIN apr01_appr a ON a.apr01_appr_id = emp45_appr_id
  		LEFT OUTER JOIN apr01_appr b ON b.apr01_appr_id = emp45_final_appr_id
 WHERE	emp45_company_id = #{companyId}
   AND	emp45_std_year = #{stdYear}
   AND	emp45_std_term_cd = #{stdTermCode}

SELECT emp43_eval_target_id AS eval_target_id, emp43_eval_list_std_id AS eval_list_std_id, emp43_std_year AS std_year, emp43_std_term_cd AS std_term_cd, emp43_person_id AS person_id, emp43_order_eval_nm AS order_eval_nm, emp43_org_head_nm AS org_head_nm, emp43_pos_nm AS pos_nm, emp43_person_nm AS person_nm, emp43_org_nm AS org_nm, emp43_hire_date_str AS hire_date_str, emp43_work_year AS work_year, emp43_date_str AS date_str, emp43_order_score AS order_score, emp43_order_grade AS order_grade, emp43_order_status AS order_status, emp43_order_reason AS order_reason, emp43_first_eval_reason AS first_eval_reason, emp43_second_eval_reason AS second_eval_reason FROM (
SELECT * , f_cdnm('EmpEvalTermCode', emp43_std_term_cd, emp43_company_id, f_sysdate()) AS emp43_std_term_nm , ( CASE WHEN emp43_eval_start_date <= emp01_hire_date THEN TO_CHAR(emp01_hire_date,'yyyy-MM-dd') || ' ~ ' || emp43_eval_close_date ELSE TO_CHAR(emp43_eval_start_date,'yyyy-MM-dd') || ' ~ ' || emp43_eval_close_date END ) AS emp43_date_str , TO_CHAR(emp01_hire_date,'yyyy-MM-dd') AS emp43_hire_date_str , emp01_hire_date AS emp43_hire_date , f_get_datediff(emp01_hire_date, emp43_eval_close_date, '1') AS emp43_work_year , ( SELECT CASE WHEN COALESCE(emp03_org_head_yn, 'false') = 'true' THEN '조직장' ELSE '조직원' END FROM emp03_trans WHERE emp03_person_id = emp43_person_id AND emp03_trans_date IN ( SELECT MAX(emp03_trans_date) FROM emp03_trans WHERE emp03_person_id = emp43_person_id AND emp03_trans_date <= (emp43_std_year||'-12-31')::date ) ) AS emp43_org_head_nm , f_get_empTrans(emp43_person_id, f_sysdate()::date, 'pos_nm') AS emp43_pos_nm , f_get_empTrans(emp43_person_id, f_sysdate()::date, 'title_nm') AS emp43_title_nm , f_emp_kor_nm(emp43_person_id) AS emp43_person_nm , f_get_empTrans(emp43_person_id, f_sysdate()::date, 'org_code_nm') AS emp43_org_nm , ( CASE WHEN emp43_first_evaluator_id = #{personId} THEN '1차' ELSE '2차' END ) AS emp43_order_eval_nm , ( CASE WHEN emp43_first_evaluator_id = #{personId} THEN emp43_first_eval_score ELSE emp43_second_eval_score END ) AS emp43_order_score , ( CASE WHEN emp43_first_evaluator_id = #{personId} THEN ( SELECT emp42_grade FROM emp42_eval_grade WHERE emp42_eval_grade_id = f_get_empEvalGradeId(emp40_eval_list_std_id, emp43_first_eval_score) ) ELSE ( SELECT emp42_grade FROM emp42_eval_grade WHERE emp42_eval_grade_id = f_get_empEvalGradeId(emp40_eval_list_std_id, emp43_second_eval_score) ) END ) AS emp43_order_grade , ( CASE WHEN emp43_first_evaluator_id = #{personId} THEN CASE WHEN COALESCE(emp43_first_eval_end_yn, 'false') = 'true' THEN '완료' WHEN ( SELECT COUNT(emp44_eval_write_id) FROM emp44_eval_write WHERE emp43_eval_target_id = emp44_eval_target_id AND emp44_evaluator_id = #{personId} ) > 0 THEN '작성중' ELSE '' END ELSE CASE WHEN COALESCE(emp43_second_eval_end_yn, 'false') = 'true' THEN '완료' WHEN ( SELECT COUNT(emp44_eval_write_id) FROM emp44_eval_write WHERE emp43_eval_target_id = emp44_eval_target_id AND emp44_evaluator_id = #{personId} ) > 0 THEN '작성중' ELSE '' END END ) AS emp43_order_status , ( CASE WHEN emp43_first_evaluator_id = #{personId} THEN CASE WHEN ( SELECT COALESCE(emp42_reason_yn, 'false') FROM emp42_eval_grade WHERE emp42_eval_grade_id = f_get_empEvalGradeId(emp40_eval_list_std_id, emp43_first_eval_score) ) = 'true' THEN CASE WHEN emp43_first_eval_reason IS NOT NULL THEN '작성완료' ELSE '작성필요' END ELSE '' END ELSE CASE WHEN ( SELECT COALESCE(emp42_reason_yn, 'false') FROM emp42_eval_grade WHERE emp42_eval_grade_id = f_get_empEvalGradeId(emp40_eval_list_std_id, emp43_second_eval_score) ) = 'true' THEN CASE WHEN emp43_second_eval_reason IS NOT NULL THEN '작성완료' ELSE '작성필요' END ELSE '' END END ) AS emp43_order_reason FROM emp43_eval_target INNER JOIN emp40_eval_list_std ON emp43_eval_list_std_id = emp40_eval_list_std_id INNER JOIN emp01_person ON emp01_person_id = emp43_person_id WHERE emp43_company_id = #{companyId} AND emp43_std_year = #{stdYear} AND emp43_std_term_cd = #{stdTermCode} AND ( emp43_first_evaluator_id = #{personId} OR emp43_second_evaluator_id = #{personId} ) AND UPPER(CONCAT(f_get_empTrans(emp43_person_id,f_sysdate()::date,'pos_nm') ,f_emp_kor_nm(emp43_person_id) ,f_get_empTrans(emp43_person_id,f_sysdate()::date,'org_code_nm'))) LIKE UPPER(#{searchText})
) t

mapper.update:
UPDATE emp43_eval_target


   SET emp43_first_eval_reason  = #{reason}


   SET emp43_second_eval_reason = #{reason}


 WHERE emp43_eval_target_id = #{evalTargetId}
   AND emp43_company_id = #{companyId}
   AND (emp43_first_evaluator_id = #{personId} OR emp43_second_evaluator_id = #{personId})

UPDATE emp43_eval_target


   SET emp43_first_eval_end_yn = #{endYn}
     , emp43_first_eval_score  =


   SET emp43_second_eval_end_yn = #{endYn}
     , emp43_second_eval_score  =




        ( SELECT SUM(emp44_eval_grade_score)
            FROM emp44_eval_write
           WHERE emp44_evaluator_id = #{personId}
             AND emp44_eval_target_id = emp43_eval_target_id )

    NULL

 WHERE emp43_eval_target_id = #{evalTargetId}
   AND emp43_company_id = #{companyId}
   AND (emp43_first_evaluator_id = #{personId} OR emp43_second_evaluator_id = #{personId})

